-- 0145 (19 Nov 2026, APPLIED LIVE: additive): Reel checks — copied-from-another-app watermarks + feed quality (founder audit).
-- One row per Reel. The audit (5 frames per video + the poster, AWS Rekognition DetectText / DetectLabels) filled it on 19 Nov.
-- Nothing here hides or changes a Reel: the founder decides. RLS on, no policy: only the service role / admin RPCs (0147) read it.
create table if not exists public.kr8_reel_copy_checks (
  post_id     uuid primary key references public.kr8_posts(id) on delete cascade,
  checked_at  timestamptz not null default now(),
  copied      boolean not null default false,
  copy_kind   text check (copy_kind in ('app_watermark','stock_watermark','ai_watermark','handle_only')),
  watermark   text,                       -- the text seen, e.g. 'TikTok'
  evidence    jsonb not null default '[]'::jsonb,   -- [{text, at ('poster' | '12.3s'), why}]
  brightness  numeric,                    -- mean 0-255 over the frames (< 35 = very dark)
  sharpness   numeric,                    -- median Laplacian variance at 360x640 (< 60 = blurry)
  has_person  boolean,
  setting     text,                       -- home | venue | outdoors | indoors | unknown
  venue_set   boolean,
  duration_s  numeric,
  labels      jsonb,                      -- top AWS labels
  verdict     text check (verdict in ('KEEP_IN_FEED','SUGGEST_FEED_OFF')),
  reasons     text[] not null default '{}',
  source      text not null default 'audit'   -- audit | auto (0147 robot)
);
alter table public.kr8_reel_copy_checks enable row level security;
revoke all on public.kr8_reel_copy_checks from anon, authenticated;

insert into public.kr8_reel_copy_checks (post_id, copied, copy_kind, watermark, evidence, brightness, sharpness, has_person, setting, venue_set, duration_s, labels, verdict, reasons, source)
select x.post_id, x.copied, x.copy_kind, x.watermark, coalesce(x.evidence,'[]'::jsonb), x.brightness, x.sharpness, x.has_person, x.setting, x.venue_set, x.duration_s, x.labels, x.verdict,
       coalesce(array(select jsonb_array_elements_text(x.reasons)), '{}'), 'audit'
